function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 50) return 'nums needs 1 to 50 values.';
  if (nums.some(v => v < 0 || v > 50)) return 'Each value is between 0 and 50.';
  if (k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
  return null;
}

