function largestInteger(nums, k) {
  const n = nums.length;
  if (k === n) {
    return Math.max(...nums);
  }
  const count = new Array(51).fill(0);
  for (const value of nums) {
    count[value]++;
  }
  if (k === 1) {
    for (let value = 50; value >= 0; value--) {
      if (count[value] === 1) {
        return value;
      }
    }
    return -1;
  }
  let best = -1;
  if (count[nums[0]] === 1) {
    best = nums[0];
  }
  if (count[nums[n - 1]] === 1) {
    best = Math.max(best, nums[n - 1]);
  }
  return best;
}

