function largestInteger(nums, k) {
  // For every value, count the windows of length k that contain it.
  let best = -1;
  for (const x of new Set(nums)) {
    let windows = 0;
    for (let start = 0; start + k <= nums.length; start++) {
      if (nums.slice(start, start + k).includes(x)) windows++;
    }
    if (windows === 1) best = Math.max(best, x);
  }
  return best;
}

