function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 50 : int(1, 8);
  // A small top value forces repeats; the full range 0..50 gives mostly distinct values.
  const top = rand() < 0.5 ? int(0, 4) : 50;
  const nums = Array.from({ length: n }, () => int(0, top));
  // k = 1 and k = n are special cases, so pick them often.
  const pick = rand();
  const k = pick < 0.2 ? 1 : pick < 0.4 ? n : int(1, n);
  return [nums, k];
}
